"""Execute only projected pure shape/fixture functions, never DB/session cases."""
from pathlib import Path
import base64,importlib.util,json,subprocess,unittest
HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('worker40_projection_tests',HERE/'projection.py');p=importlib.util.module_from_spec(spec);spec.loader.exec_module(p)
class Tests(unittest.TestCase):
 def test_real_old_fixture_and_new_state_shape_project_without_modifying_RPC_helpers(self):
  source,proof=p.project('a'*64);self.assertTrue(proof['exact_inverse_byte_equal']);url='data:text/javascript;base64,'+base64.b64encode(source.encode()).decode()
  program="import fs from'node:fs';import assert from'node:assert/strict';const m=await import("+json.dumps(url)+");const tables=['candidate_asset_config','frame_extraction_config','presentation_processing_config','review_processing_config','specs_pipeline_config'];const value={schema40:{canonical:{base:{data:Object.fromEntries(tables.map(t=>[t,{sha:'unchanged'}]))},processing_config:Object.fromEntries(tables.map(t=>[t,{table_hash:'old',public:{enabled:true,native_image_id:'pin'}}]))},intents:{count:0}},lifecycle:{queued:0},oauth_count_only:{claims_count:2}};const result=m.expectedFlags(value,tables,false);assert.equal(value.schema40.canonical.processing_config.specs_pipeline_config.public.enabled,true);for(const t of tables){assert.equal(result.schema40.canonical.processing_config[t].public.enabled,false);assert(!Object.hasOwn(result.schema40.canonical.base.data,t));assert(!Object.hasOwn(result.schema40.canonical.processing_config[t],'table_hash'));}assert.deepEqual(result.lifecycle,value.lifecycle);assert.deepEqual(result.oauth_count_only,value.oauth_count_only);const raw=fs.readFileSync("+json.dumps(str(p.MAIN/'development/m07/worker38-concurrency/fixture.sql'))+");const adapted=m.adaptFixture(raw,{database:'project39',system_identifier:'1234567890123456789'},'00000000-0000-4000-8000-000000000001');assert(adapted.text.includes('(select count(*)from supabase_migrations.schema_migrations)<>40'));assert(adapted.text.includes(\"(select max(version)from supabase_migrations.schema_migrations)<>'20261102085405'\"));assert.equal(adapted.actual_rpc_implementation_copied_or_modified,false);assert(!adapted.text.includes('update eps.specs_pipeline_config set enabled=true'));assert(adapted.text.includes('public.eps_submit_specs'));assert(adapted.text.includes('public.eps_retry_job'));"
  result=subprocess.run(['C:/Program Files/nodejs/node.exe','--input-type=module','-e',program],capture_output=True,timeout=15);self.assertEqual(result.returncode,0,result.stderr[:300])
if __name__=='__main__':unittest.main()
